<script module lang="ts">
/**
 * A collapsible section showing the model's reasoning (`design/components/reasoning-disclosure.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/reasoning-disclosure.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import * as zag from '@zag-js/collapsible'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  agentMember,
  attributes,
  joinSlot,
  normalizeProps,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/reasoning-disclosure.module.css'

export interface ReasoningDisclosureProps {
  /**
   * The reasoning, as a `Markdown size="sm"` or a `StreamingText size="sm"`.
   */
  children: Snippet
  /**
   * Whether it starts open, closed by default so the reasoning is available but out of the way.
   */
  defaultOpen?: boolean
  /**
   * The trigger's text in the app's words, such as "Thinking…" or "Thought for 12 seconds".
   */
  label: string
  onOpenChange?: (open: boolean) => void
  /**
   * The controlled open state, paired with `onOpenChange` as in Radix.
   */
  open?: boolean
  /**
   * Whether the model is still reasoning, which spins the mark and sets `aria-busy` on the root.
   */
  streaming?: boolean
}
</script>

<script lang="ts">
let {
  children,
  defaultOpen = false,
  label: labelOwn,
  onOpenChange,
  open,
  streaming = false,
}: ReasoningDisclosureProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let trigger = $state<HTMLElement | null>(null)
const documentDirection = useDirection(() => trigger)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      open: open,
      defaultOpen: defaultOpen,
      onOpenChange: (details) => {
        onOpenChange?.(details.open)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ReasoningDisclosure',
    element: () => trigger,
    state: () => ({ expanded: api.open, streaming: streaming }),
    actions: { expand: () => api.setOpen(true), collapse: () => api.setOpen(false) },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    {...attributes(api.getRootProps())}
    class={styles.root}
    data-streaming={(streaming) ? '' : undefined}
    aria-busy={(streaming) ? true : undefined}
    data-member="reasoning-disclosure"
    ><button bind:this={trigger} {...attributes(api.getTriggerProps())} class={styles.trigger}
      ><span class={[styles.mark, streaming ? styles.spinning : undefined]}
        ><Icon name={streaming ? 'loading' : 'reasoning'} size="sm"
      /></span
      ><span class={styles.label}>{label}</span
      ><span class={styles.chevron}><Icon name="down" size="sm" /></span
    ></button
    ><div
      {...attributes(api.getContentProps())}
      class={styles.content}
      style:--radix-collapsible-content-height={Object(api.getContentProps().style)['--height']}
      ><div class={styles.inner}>{@render children?.()}</div
    ></div
  ></div
>{/if
}{@render joined.end?.()}
